(window.GIM_TS=window.GIM_TS||{})["Moed Katan.2"]={"from":48,"a":[["\u0003ואלו קרעין\u0004 של אבילות \u0003שאין מתאחין\u0004 לעולם: \u0003הקורע על אביו, ועל אמו, ועל רבו שלימדו תורה, ועל נשיא, ועל אב בית דין\u0004 שמתו, \u0003ו\u0004הקורע \u0003על שמועות הרעות, ועל ברכת השם\u0004 (כששומע שמקללים שם שמים), \u0003ועל ספר תורה שנשרף, ועל ערי יהודה\u0004 שחרבו, \u0003ועל המקדש, ועל ירושלים.\u0004 וכך הוא עושה כשבא לירושלים החרבה: \u0003וקורע על מקדש ומוסיף\u0004 בקריעה \u0003על ירושלים.\u0004","את ההלכה הזו מפרטים: \u0003אביו ואמו ורבו שלימדו תורה מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בסיפור עליית אליהו בסערה השמימה: \u0003\"ואלישע ראה והוא מצעק אבי אבי רכב ישראל ופרשיו\"\u0004 (מלכים ב' ב, יב), ואנו למדים: \u0003\"אבי אבי\"\u0004 — \u0003זה\u0004 בא לרבות גם \u0003אביו ואמו, \"רכב ישראל ופרשיו\" — זה רבו שלימדו תורה.\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות,\u0006 וכיצד נובע הדבר מכאן\u0005]\u0006 שהכוונה לרבו? ומסבירים: \u0003כ\u0004מו שהיה \u0003מתרגם רב יוסף\u0004 פסוק זה: \u0003רבי רבי דטב להון\u0004 \u0005[שטוב להם]\u0006 \u0003לישראל בצלותיה\u0004 \u0005[בתפילתו]\u0006 \u0003מרתיכין ופרשין\u0004 \u0005[מרכב ופרשים].\u0006","\u0003ו\u0004שקרעים אלה \u0003לא מתאחין מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחזק בבגדיו ויקרעם לשנים קרעים\"\u0004 (מלכים ב', ב, יב), \u0003ממשמע שנאמר \"ויקרעם\" איני יודע שלשנים? אלא\u0004 כשאומר \"לשנים קרעים\" \u0003מלמד שקרועים ועומדים לשנים לעולם,\u0004 שלעולם אין מאחים אותם לגמרי, והם נראים איפוא תמיד כקרועים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 הלא \u0003אליהו חי הוא\u0004 ולא מת, ומדוע קרע עליו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיון דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא ראהו עוד\"\u0004 (מלכים ב', ב, יב), הרי \u0003לגבי דידיה\u0004 \u0005[לגביו]\u0006 \u0003כמת דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ולכן קרע עליו.","\u0003נשיא ואב בית דין ושמועות הרעות מנלן\u0004 \u0005[מניין לנו]\u0006 שקורעים עליהם — \u0003דכתיב\u0004 \u0005[שנאמר],\u0006 שכאשר שמע דוד על מפלת ישראל ומות שאול ובניו \u0003\"ויחזק דוד בבגדו ויקרעם וגם כל האנשים אשר אתו. ויספדו ויבכו ויצמו עד הערב על שאול ועל יהונתן בנו ועל עם ה' ועל בית ישראל כי נפלו בחרב\"\u0004 (שמואל ב' א, יא-יב).","ומבארים לענייננו: \u0003\"שאול\" — זה נשיא\u0004 שהרי היה מלך ישראל, \u0003\"יהונתן\" — זה אב בית דין, \"על עם ה' ועל בית ישראל\" — אלו שמועות הרעות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב בר שבא לרב כהנא: ואימא\u0004 \u0005[ואמור]\u0006 שאין קורעים \u0003עד דהוו כולהו\u0004 \u0005[שיהיו כולם\u0006 יחד\u0005],\u0006 שרק באסון גדול כזה קורעים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"על\" \"על\" הפסיק הענין,\u0004 שהרי נאמר בכל אחד \"על\", על שאול ועל יהונתן, ולא אמרם יחד, משמע שעל כל אחד מהם לחוד ראוי לקרוע.","ושואלים: \u0003ומי קרעינן\u0004 \u0005[והאם קורעים אנו]\u0006 על \u0003שמועות הרעות? והא\u0004 \u0005[והרי]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל: קטל\u0004 \u0005[הרג]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003תריסר אלפי יהודאי\u0004 \u0005[שנים עשר אלף יהודים]\u0006 \u0003במזיגת קסרי, ולא קרע?!\u0004 ומשיבים: \u0003לא אמרו\u0004 שיש לקרוע על שמועה רעה \u0003אלא\u0004 באסון \u0003ברוב צבור וכמעשה שהיה\u0004 במות שאול שהיתה זו מפלת עם ישראל.","ושואלים בדרך אגב: \u0003ומי קטל\u0004 \u0005[והאם הרג]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003יהודאי\u0004 \u0005[יהודים]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003לשמואל: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 ברכה על ש\u0003לא קטלי\u0004 \u0005[הרגתי]\u0006 \u0003יהודי מעולם!\u0004 ומשיבים: שבור המלך לא הרג יהודים ברצון, אולם \u0003התם אינהו גרמי לנפשייהו\u0004 \u0005[שם הם עצמם גרמו לעצמם],\u0006 ש\u0003אמר ר' אמי\u0004 בלשון גוזמא: \u0003לקל יתירי\u0004 \u0005[לקול מיתרי\u0006 כנורות\u0005]\u0006 של \u0003מזיגת קסרי, פקע שורא\u0004 \u0005[נבקעו חומות]\u0006 \u0003לודקיא,\u0004 שעשו יושבי העיר שמחה גדולה כשמרדו במלך שבור, ולכן, כיון שנלחמו בו ומרדו במלכותו הוצרך להרגם.","ולענייננו, \u0003על ברכת\u0004 (בלשון נקיה, והכוונה לקללה) \u0003השם מנלן\u0004 \u0005[מניין לנו]\u0006 שקורעים? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבא אליקים בן חלקיה אשר על הבית ושבנא הספר ויואח בן אסף המזכיר אל חזקיהו קרועי בגדים\"\u0004 (מלכים ב' יח, לז), על זלזול השם ששמעו מפי רבשקה.","באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד השומע\u0004 ברכת ה' \u0003ואחד השומע מפי השומע\u0004 — \u0003חייב לקרוע. והעדים\u0004 המעידים על מי שחטא בחטא זה \u0003אינן חייבין לקרוע\u0004 כשחוזרים בעדותם על הדברים ששמעו, מפני \u0003שכבר קרעו בשעה ששמעו.\u0004","ותוהים: ואם קרעו \u0003בשעה ששמעו מאי הוי\u0004 \u0005[מה יש]?\u0006 \u0003הא קא שמעי השתא\u0004 \u0005[הרי הם שומעים עכשיו]\u0006 פעם נוספת! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי כשמע המלך חזקיהו ויקרע את בגדיו\"\u0004 (מלכים ב', יט, א), משמע \u0003המלך קרע והם לא קרעו\u0004 משום שכבר קרעו בפעם הראשונה.","\u0003ו\u0004שקרעים אלה \u0003לא מתאחין מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 בגזירה שווה \u0003\"קריעה\" \"קריעה\"\u0004 מהקריעה הכתובה אצל אלישע ואליהו. ושם למדנו שהם קרעים שאינם מתאחים.","\u0003ספר תורה שנשרף מנלן\u0004 \u0005[מניין לנו]?\u0006 שקורעים עליו — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי כקרוא יהודי שלש דלתות וארבעה יקרעה בתער הספר והשלך אל האש אשר אל האח\"\u0004 (ירמיהו לו, כג). לעצם הענין שואלים; \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלש דלתות וארבעה\"\u0004 ומדוע קרע את הספר רק אז?","ומסבירים: \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003ליהויקים: כתב ירמיה ספר קינות\u0004 על המפלה העתידה של ירושלים. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מה כתיב ביה\u0004 \u0005[נאמר בו]?\u0006 אמרו לו פסוק ראשון: \u0003\"איכה ישבה בדד\"\u0004 (איכה א, א). \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא מלכא\u0004 \u0005[אני מלך]\u0006 ולי אין הדבר נוגע. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 פסוק שני: \u0003\"בכו תבכה בלילה\"\u0004 (איכה א, ב). אמר להם: \u0003אנא מלכא\u0004 \u0005[אני מלך]\u0006 ואין זה מדובר בי. אמרו לו פסוק שלישי: \u0003\"גלתה יהודה מעני\"\u0004 (איכה א, ג). אמר להם: \u0003אנא מלכא\u0004 \u0005[אני מלך].\u0006 אמרו לו: \u0003\"דרכי ציון אבלות\"\u0004 (איכה א, ד). אמר להם: \u0003אנא מלכא\u0004 \u0005[אני מלך].\u0006 ואלה הן ארבע דלתות (פסוקים) שקרא תחילה.","אמרו לו פסוק נוסף: \u0003\"היו צריה לראש\"\u0004 (איכה א, ה), שתתבטל מלכותו. כיון ששמע כך \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמרה?\u0004 אמרו לו: זהו המשכו של הפסוק \u0003\"כי ה' הוגה על רב פשעיה\"\u0004 (איכה א, ה). \u0003מיד קדר\u0004 (חתך) \u0003כל אזכרות\u0004 (איכה א, ה) \u0003שבה, ושרפן באש. והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"ולא פחדו ולא קרעו את בגדיהם\"\u0004 (ירמיהו לו, כד), \u0003מכלל\u0004 הדברים אתה למד \u0003דבעו למיקרע\u0004 \u0005[ש\u0006היו \u0005צריכים לקרוע]\u0006 כשראו דבר זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אימר\u0004 \u0005[אמור]\u0006 \u0003משום שמועות הרעות\u0004 הכתובות שם היו צריכים לקרוע? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003שמועות רעות בההיא שעתא מי הוו\u0004 \u0005[באותה שעה האם היו]?\u0006 הלא היו אלה דברי נבואה, ולא שמועות ממשיות.","\u0003אמר ר' חלבו אמר רב הונא: הרואה ספר תורה שנקרע\u0004 — \u0003חייב לקרוע שתי קריעות; אחד על הגויל\u0004 שנקרע, \u0003ואחד על הכתב. שנאמר: \"אחרי שרף המלך את המגלה ואת הדברים\"\u0004 (ירמיהו לו, כז), משמע שעל כל אחד מאלה יש לקרוע.","מסופר: \u0003ר' אבא ורב הונא בר חייא הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003ר' אבא, בעא לאפנויי\u0004 \u0005[רצה\u0006 ר' אבא \u0005להיפנות\u0006 לצרכיו\u0005],\u0006 \u0003שקליה לטוטפתיה אחתיה אבי סדיא\u0004 \u0005[הוריד את הטוטפת שלו,\u0006 התפילין שבראשו, ו\u0005הניחה על המצע]\u0006 שהיה יושב עליו. \u0003אתאי בת נעמיתא בעא למיבלעיה\u0004 \u0005[באה בת יענה\u0006 ו\u0005רצתה לבלוע אותם,\u0006 את התפילין\u0005],\u0006","\u0003אמר: השתא איחייבין לי\u0004 \u0005[עכשיו,\u0006 אילו היתה בולעת אותם, \u0005הייתי חייב]\u0006 \u0003שתי קריעות, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מנא לך הא\u0004 \u0005[מניין לך\u0006 דבר \u0005זה]?\u0006 \u0003והא בדידי הוה עובדא\u0004 \u0005[והרי בי היה מעשה\u0006 דומה\u0005]\u0006 \u0003ואתאי לקמיה\u0004 \u0005[ובאתי לפני]\u0006 \u0003רב מתנה\u0004 לשאול \u0003ולא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005],\u0006 \u0003אתאי לקמיה\u0004 \u0005[ובאתי לפני]\u0006 \u0003רב יהודה ואמר לי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: לא אמרו\u0004 שצריך לקרוע \u0003אלא\u0004 כשנקרע ספר התורה או ספר קודש אחר \u0003בזרוע\u0004 (באונס ובכח), \u0003וכמעשה שהיה\u0004 ביהויקים.","שקורעים על \u0003ערי יהודה מנלן\u0004 \u0005[מניין לנו] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבאו אנשים משכם משלו ומשמרון שמנים איש מגלחי זקן וקרעי בגדים ומתגדדים ומנחה ולבונה בידם להביא בית ה' \"\u0004(ירמיהו מא, ה), משמע שכשראו את החורבן קרעו.","\u0003אמר ר' חלבו אמר עולא ביראה אמר ר' אלעזר: הרואה ערי יהודה בחורבנן, אומר: \"ערי קדשך היו מדבר\"\u0004 (ישעיהו סד, ט), \u0003וקורע.\u0004 הרואה \u0003ירושלים בחורבנה — אומר: \"ציון מדבר היתה ירושלים שממה\"\u0004 (ישעיהו סד, ט), \u0003וקורע.\u0004 הרואה \u0003בית המקדש בחורבנו — אומר: \"בית קדשנו ותפארתנו אשר הללוך אבתינו היה לשרפת אש וכל מחמדינו\u0004 היה \u0003לחרבה\"\u0004 (ישעיהו סד, י), \u0003וקורע.\u0004","שנינו בברייתא ש\u0003קורע על מקדש, ומוסיף\u0004 על הקרע הראשון וקורע \u0003על ירושלים. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]:\u0006 \u0003אחד השומע ואחד הרואה\u0004 חורבן מקומות הקודש, \u0003כיון שהגיע לצופים — קורע, וקורע על מקדש בפני עצמו ועל ירושלים בפני עצמה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאינו קורע על ירושלים קריעה בפני עצמה אלא מוסיף על הקריעה שקרע למקדש, הרי זה באופן ש\u0003פגע במקדש\u0004 וראה אותו חרב \u0003ברישא\u0004 \u0005[בתחילה].\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שקורע קריעה אחת על ירושלים, וכשרואה את המקדש קורע קריעה מיוחדת, הרי זה כש\u0003פגע בירושלים ברישא\u0004 \u0005[בתחילה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003וכולן\u0004 כל אותם הקרעים הללו \u0003רשאין לשוללן\u0004 בתפירה גסה \u0003ולמוללן\u0004 (לקפל אותם ולתפור) \u0003וללוקטן ולעשותן כמין סולמות\u0004 בתפירה לא מדוייקת, \u0003אבל לא לאחותן\u0004 בתפירה מעולה.","\u0003אמר רב חסדא:\u0004"],["\u0003ובאיחוי אלכסנדרי\u0004 (כדרך שעושים באלכסנדריה) שהוא איחוי מעולה, עד שאין הקרע ניכר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הקורע מתוך השלל\u0004 (במקום שנקרע ואיחוהו איחוי גס) או \u0003מתוך המלל\u0004 (שולי הבגד) או \u0003מתוך הלקט,\u0004 או \u0003מתוך הסולמות\u0004 (מקום תפר בתפרים גסים) \u0003לא יצא\u0004 ידי חובת קריעה. קרע \u0003מתוך האיחוי — יצא,\u0004 מפני שזה כקריעת בגד שלם. \u0003אמר רב חסדא:\u0004 אף כאן \u0003ובאיחוי אלכסנדרי\u0004 ולא באיחוי סתם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בגד שעושה בו קריעה בקצה העליון \u0003רשאי להופכו\u0004 כך שיבוא חלקו העליון \u0003למטה ו\u0004אז יכול \u0003לאחותו. ר' שמעון בן אלעזר אוסר לאחותו\u0004 גם כך. ומעירים: \u0003וכשם שהמוכר\u0004 שעשה קריעה בבגדו באבלו \u0003אסור לאחותו — כך הלוקח\u0004 (הקונה) ממנו \u0003אסור לאחותו. ולפיכך מוכר צריך להודיעו ללוקח\u0004 שקרע זה הוא קרע של אבילות שאינו ניתן לאיחוי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תחילת קריעה — טפח, ותוספת\u0004 אם צריך לקרוע על מתים אחרים ורוצה לקרוע בבגד זה — \u0003שלש אצבעות,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: תחילת קריעה\u0004 — \u0003שלש אצבעות, ותוספת\u0004 — \u0003כל שהו.\u0004","\u0003אמר עולא: הלכה כר' מאיר ב\u0004תחילת \u0003קריעה\u0004 שהיא טפח, \u0003והלכה כר' יהודה בתוספת\u0004 שהיא כל שהוא. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יוסי אומר: תחילת קריעה\u0004 — \u0003טפח, ותוספת\u0004 — \u0003כל שהו,\u0004 ומקובלים אנו שהלכה כר' יוסי כנגד חביריו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אמרו לו\u0004 לאדם ש\u0003מת אביו, וקרע\u0004 עליו ואחר כך אמרו לו ש\u0003מת בנו, והוסיף\u0004 באותו קרע, קרע \u0003תחתון\u0004 שקרע על בנו — \u0003מתאחה,\u0004 שהרי על כל המתים מותר לאחות את הקרע לאחר זמן האבילות, \u0003עליון — אינו מתאחה,\u0004 שקרע שעל אביו אינו מתאחה.","שמע ש\u0003מת בנו וקרע\u0004 עליו, ואחר כך שמע ש\u0003מת אביו והוסיף\u0004 בקרע, החלק \u0003עליון\u0004 שקרע על הבן — \u0003מתאחה, תחתון\u0004 — \u0003אינו מתאחה.\u0004","אמרו לו בבת אחת ש\u0003מת אביו,\u0004 ש\u0003מת\u0004 ה\u0003אמו,\u0004 ש\u0003מת אחיו,\u0004 ש\u0003מתה אחותו — קורע קרע אחד לכולן.\u0004 ומוסיף לכל אחד ואחד. \u0003ר' יהודה בן בתירה אומר: על\u0004 הקרובים \u0003כולן קרע אחד, ועל אביו ואמו קרע אחד, לפי שאין מוסיפין על קרע אביו ואמו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 מדוע אין מוסיפים על קרע זה? \u0003אמר רב נחמן בר יצחק: לפי שאינן בתוספת\u0004 שאינו בדין שיהיו בתוספת, כיון שיש לו לאדם רק אב ואם אחד, ואינו יכול להוסיף עליהם.","\u0003אמר שמואל: הלכה כר' יהודה בן בתירה.\u0004 ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 כלל: \u0003הלכה כדברי המיקל באבל,\u0004 וכאן פוסק הוא כדעת המחמיר! ומשיבים: \u0003אבילות לחוד —\u0004 ובה אכן יש להקל, \u0003קריעה לחוד.\u0004","ולהלכה, \u0003עד היכן קורע\u0004 אם מוסיף והולך בקרעים — \u0003עד טיבורו, ויש אומרים: עד לבו.\u0004 ומוסיפים, \u0003אף על פי שאין ראיה לדבר,\u0004 שעד כאן קורעים, יש \u0003זכר\u0004 ורמז \u0003לדבר, שנאמר: \"וקרעו לבבכם ואל בגדיכם\"\u0004 (יואל ב, יג) ורמז הוא שאף קריעת הבגדים היא עד הלב.","\u0003הגיע לטיבורו\u0004 אינו קורע הלאה באותו מקום, אלא \u0003מרחיק שלש אצבעות\u0004 ממקום הקרע הראשון \u0003וקורע\u0004 קרע חדש. \u0003נתמלא\u0004 הבגד קרעים \u0003מלפניו — מחזירו\u0004 הופך את הבגד \u0003לאחוריו\u0004 וקורע בצד האחר. \u0003נתמלא מלמעלה — הופכו מלמטה.\u0004 אבל \u0003הקורע מלמטה ומן הצדדין — לא יצא,\u0004 שקריעה אינה אלא מלמעלה. \u0003אלא שכהן גדול\u0004 שאסור לו לקרוע ולפרום באבלו \u0003פורם מלמטה,\u0004 שעושה סימן מסויים לאבלו.","\u0003פליגו בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב מתנה ומר עוקבא, ותרוייהו משמיה דאבוה\u0004 \u0005[ושניהם\u0006 אמרו זאת \u0005משם אביו]\u0006 של \u0003שמואל ולוי. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כל שבעה\u0004 לאבלו, אם שמע שמת לו מת אחר \u0003קורע\u0004 קריעה אחרת, ואם שמע \u0003לאחר שבעה — מוסיף\u0004 על קרע ראשון. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כל שלשים קורע\u0004 קרע חדש, \u0003לאחר שלשים מוסיף.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003כל שבעה קורע, אמאי\u0004 \u0005[מדוע]\u0006 הוא אומר שאין להסתפק בתוספת קריעה על הראשונה — בודאי משום ש\u0003לא ניתן לשוללו\u0004 עד סוף השבעה, ולכן אם יוסיף ייראה רק כממשיך את הקרע הקודם, \u0003אלא הא\u0004 \u0005[זה]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 קרע בבגד אשה, \u0003האשה שוללתו לאלתר\u0004 \u0005[מיד],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהיא יכולה להוסיף על הקרע אף בתוך שבעה?!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום כבוד אשה הוא\u0004 שהתירו לה לשלול אבל מן הדין נחשב הקרע כאילו הוא קרוע עדיין, ולכן אינה מוסיפה עליו.","ועוד שאל: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003כל שלשים קורע\u0004 ואינו מוסיף, \u0003אמאי\u0004 \u0005[מדוע] — כיון ש\u0006\u0003לא ניתן\u0004 קרע זה \u0003לאחותו,\u0004 ועדיין נראה כקרוע, \u0003אלא\u0004 אם כן קרע שעשה \u0003לאביו ולאמו\u0004 שמתו, ש\u0003לא ניתן לאחותו לעולם, הכי נמי\u0004 \u0005[כך גם כן]\u0006 הדין הוא שאסור יהיה להוסיף עליו?!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום כבוד אביו ואמו הוא\u0004 שאינו מאחה, אבל מעיקר הדין נחשב קרע זה כאילו נתאחה, ואפשר להוסיף עליו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היוצא בבגד קרוע\u0004 (שקרע קודם לכן מסיבה אחרת) \u0003לפני המת\u0004 שנראה כאילו קרע עליו — \u0003הרי זה גוזל את המתים\u0004 שלא קרע על מת זה, \u0003ואת החיים\u0004 הרואים אותו והסבורים שקרע לכבוד המת, ואינו אלא מרמה אותם בכך.","\u0003רבן שמעון בן גמליאל אומר: האומר לחבירו \"השאילני חלוקך ואלך ואבקר את אבא שהוא חולה\", והלך ומצאו\u0004 את אביו \u0003שמת — קורע\u0004 את החלוק, \u0003ומאחו, וכשיבא לביתו מחזיר לו חלוקו, ונותן לו דמי קרעו\u0004 שערך החלוק נפחת על ידי כך. \u0003ואם לא הודיעו\u0004 שהוא הולך לבקר חולה — \u0003הרי זה לא יגע בו,\u0004 שהרי לא קיבל כל רשות לקרוע בגדו של חבירו, מה שאין כן במודיע, שהמשאיל יכול להעלות אפשרות כזו על דעתו, ועל דעת כן השאיל לו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חולה שמת לו מת — אין מודיעין אותו שמת, שמא תטרף דעתו עליו\u0004 מפני הצער, שמאחר שחולה הוא אינו יכול לסבול עוגמת נפש. \u0003ואין\u0004 אחרים \u0003מקרעין בפניו\u0004 כדי שלא ידע שמת לו מת. \u0003ומשתקין את הנשים\u0004 הבוכות \u0003מפניו\u0004 כדי שלא ידע.","ועוד אמרו: \u0003ומקרעין לקטן\u0004 (לילד קטן) שהיה אבל במשפחתו \u0003מפני עגמת נפש,\u0004 שאף שהקטן איננו חייב בקריעה, מכל מקום הרי זה מוסיף עוגמת נפש לאחרים הרואים שגם בבגדי הקטן עושים קריעה. \u0003וקורעין על חמיו ועל חמותו\u0004 אף על פי שאינו מחויב להתאבל עליהם, \u0003מפני כבוד אשתו\u0004 להראות לה שהוא משתתף באבלה.","\u0003ואמר רב פפא: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003ב\"אבל רבתי\"\u0004 (מסכת שמחות): \u0003אבל לא יניח תינוק בתוך חיקו, מפני ש\u0004התינוק \u0003מביאו לידי שחוק, ונמצא מתגנה על הבריות\u0004 שרואים שהוא צוחק בזמן אבלו.","שנינו במשנה ש\u0003אין מברין\u0004 אלא \u0003על מטות זקופות. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ההולך לבית האבל, אם היה לבו גס בו\u0004 שהיו שניהם מיודדים וקרובים זה לזה — \u0003יברוהו\u0004 גם את המבקר \u0003על מטות כפויות,\u0004 שכיון שהם ידידים אין נוהגים בו כבאורח אלא כשותף באבל. \u0003ואם לאו\u0004 \u0005[לא]\u0006 שאין לבו גס בו — \u0003יברוהו על מטות זקופות.\u0004","מסופר: \u0003רבא איתרע ביה מילתא\u0004 \u0005[אירע בו דבר\u0006 של אבל\u0005],\u0006 \u0003על גביה\u0004 \u0005[נכנס אליו]\u0006 \u0003אבא בר מרתא,\u0004 ש\u0003הוא\u0004 קרוי גם \u0003אבא בר מניומי. רבא זקיף\u0004 \u0005[זקף]\u0006 את המיטה משום שנהג כמו שנוהגים בכל אדם שבא לנחם, \u0003אבא בר מרתא כפי\u0004 \u0005[כפה]\u0006 את המיטה משום שחשב שהוא מקורב, וליבו גס בו. \u0003אמר\u0004 רבא: \u0003כמה לית ביה דעתא להאי צורבא מרבנן\u0004 \u0005[אין בו דעת לתלמיד חכם זה]\u0006 שהרי הקדים רבא והראה שאיננו חושב אותו לאדם קרוב, והאורח מראה עצמו כקרוב קירבה יתירה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אבל \u0003ההולך ממקום למקום\u0004"],["\u0003אם יכול למעט בעסקו — ימעט, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003יגלגל עמהן\u0004 ישתתף בעסק עם שאר בני חבורתו, אבל לא יעשה עסק בפני עצמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מאימתי כופין\u0004 (הופכים) \u0003את המטות — משיצא\u0004 המת \u0003מפתח ביתו,\u0004 אלו \u0003דברי ר' אליעזר. ר' יהושע אומר: משיסתם הגולל\u0004 על קבר המת.","\u0003מעשה שמת\u0004 הנשיא \u0003רבן גמליאל הזקן, כיון שיצא מפתח ביתו אמר להם ר' אליעזר\u0004 לבני הבית: \u0003כפו מטותיכם. וכיון שנסתם הגולל אמר להם ר' יהושע: כפו מטותיכם. אמרו לו: כבר כפינו על פי זקן\u0004 (חכם).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מאימתי זוקפין את המטות בערב שבת,\u0004 שהרי בשבת אין אבילות נוהגת ואין כופים את המיטות וצריך לזוקפן כרגיל, הזמן לכך הוא — \u0003מן\u0004 זמן תפילת \u0003המנחה ולמעלה\u0004 (והלאה). \u0003אמר רבה בר הונא: אף על פי כן אינו יושב עליה\u0004 מיד אלא \u0003עד שתחשך. ולמוצאי שבת, אף על פי שאין לו לישב אלא יום אחד,\u0004 שמסתיימים ימי אבילותו ביום ראשון — \u0003חוזר וכופה\u0004 את המיטות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכופה מטתו, לא\u0004 את \u0003מטתו בלבד הוא כופה, אלא\u0004 את \u0003כל\u0004 ה\u0003מטות שיש לו בתוך ביתו הוא כופה. ואפילו יש לו עשר מטות בעשרה מקומות — כופה את כולן. ואפילו חמשה אחין ומת אחד — כולן כופין\u0004 בכל מקום שהם גרים.","\u0003ואם היתה מטה המיוחדת\u0004 לשימוש כארון \u0003לכלים\u0004 ולא לשינה — \u0003אין צריך לכפותה. דרגש — אין צריך לכפותו, אלא זוקפו. רבן שמעון בן גמליאל אומר: דרגש, מתיר את קרביטיו\u0004 את הלולאות שבהן מחזיקים את המצעים \u0003והוא נופל מאיליו.\u0004","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003דרגש? אמר עולא: ערסא דגדא\u0004 \u0005[מיטה של מזל],\u0006 שהיו מחזיקים בבית מיטה מקושטת למזל, ואיש לא היה משתמש בה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: אלא מעתה\u0004 לפי פירוש זה של \"דרגש\" \u0003גבי\u0004 (אצל) \u0003מלך, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 כשהמלך אבל — \u0003כל העם מסובים על הארץ, והוא,\u0004 מפני כבוד המלכות, \u0003מיסב על הדרגש. מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא אותביניה\u0004 \u0005[הושבנו אותו\u0006 עליו\u0005],\u0006 \u0003והשתא מותבינן ליה\u0004 \u0005[ועכשיו\u0006 באבילות דווקא \u0005מושיבים אותו]?\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: מאי קושיא\u0004 \u0005[מה\u0006 טיבה של \u0005הקושיה]\u0006 שהקשה רבה? \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדבר בענין\u0005]\u0006 \u0003אכילה ושתיה,\u0004 ש\u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 שלא היה אבל \u0003לא אוכליניה\u0004 \u0005[האכלנו אותו]\u0006 \u0003ולא אשקיניה\u0004 \u0005[השקינו אותו],\u0006 \u0003השתא אוכליניה ואשקיניה\u0004 \u0005[עכשיו\u0006 כשהוא אבל \u0005מאכילים ומשקים אנו אותו]\u0006 בסעודת הבראה!","\u0003אלא, אי קשיא\u0004 \u0005[אם קשה]\u0006 — \u0003הא קשיא\u0004 \u0005[זה קשה],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003דרגש אינו צריך לכפותו אלא זוקפו. ואי ערסא דגדא\u0004 \u0005[ואם מיטת המזל\u0006 הוא\u0005]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו צריך לכפותו? הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכופה מטתו — לא מטתו בלבד הוא כופה, אלא כל מטות שיש לו בתוך ביתו כופה\u0004 ובכלל זה גם מיטת מזל זו!","ודוחים: \u0003ומאי קשיא\u0004 \u0005[ומה הקושיה]\u0006 שבכך? \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 בענין\u0005]\u0006 \u0003מטה המיוחדת ל\u0004איכסון \u0003כלים, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אם היתה מטה המיוחדת לכלים\u0004 ולא לשינה — \u0003אינו צריך לכפותה,\u0004 כך גם מיטה זו שאיננה מיוחדת לשינה.","\u0003אלא, אי קשיא הא קשיא\u0004 \u0005[אם קשה, זה קשה]\u0006 מן ההמשך: \u0003רבן שמעון בן גמליאל אומר: דרגש, מתיר קרביטיו\u0004 (לולאותיו) \u0003והוא נופל מאליו. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שדרגש הוא \u0003ערסא דגדא\u0004 \u0005[מיטת מזל],\u0006 \u0003מאי קרביטין אית ליה\u0004 \u0005[מה,\u0006 איזה, \u0005לולאות יש לו],\u0006 שהרי הוא כשאר המיטות?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד החכמים],\u0006 \u0003ורב תחליפא בר מערבא שמיה\u0004 \u0005[שמו],\u0006 \u0003דהוה שכיח בשוקא דגילדאי\u0004 \u0005[שהיה מצוי בשוק עושי העורות]:\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003דרגש — ערסא דצלא\u0004 \u0005[מיטה של עור].\u0006","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003אמר ר' ירמיה: דרגש — סירוגו מתוכו,\u0004 שבתוך עצי המיטה עצמם עושים נקבים ולולאות כדי לקשור את הסירוג, ואילו \u0003מטה — סירוגה על גבה,\u0004 שמסרגים על עצי המיטה. ולכן אי אפשר להתיר את הסירוג הזה.","\u0003אמר ר' יעקב בר אחא אמר ר' יהושע בן לוי: הלכה כרבן שמעון בן גמליאל\u0004 בענין דרגש. וכיוצא בו \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר ר' יעקב בר אחא אמר ר' אסי: מטה שנקליטיה\u0004 (המוטות שמעליה) \u0003יוצאין\u0004 החוצה הרבה ולכן אם הופך אותה תישאר גבוהה כמות שהיתה — \u0003זוקפה ודיו\u0004 ואינו צריך לכפותה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003ישן\u0004 האבל \u0003על גבי כסא, על גבי אודייני\u0004 (מכתשת) \u0003גדולה\u0004 הפוכה, או \u0003על גבי קרקע — לא יצא ידי חובתו\u0004 למרות שהתענה בשנתו. \u0003אמר ר' יוחנן:\u0004 הכוונה מפני \u0003שלא קיים\u0004 מצוות \u0003כפיית המטה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מכבדין\u0004 (מטאטאים) \u0003ומרביצין\u0004 מים על עפר הרצפה \u0003בבית האבל, ומדיחין קערות וכוסות וצלוחיות וקיתוניות\u0004 (כלי שתיה) \u0003בבית האבל. ואין מביאין את המוגמר\u0004 (בשמים שמניחים על גבי גחלים לקטורת) או \u0003את הבשמים לבית האבל.\u0004","ושואלים: \u0003איני\u0004 \u0005[הכן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003בר קפרא\u0004 ברייתא זו: \u0003אין מברכין לא על המוגמר ולא על הבשמים בבית האבל.\u0004 ומכאן אפשר ללמוד כי \u0003ברוכי\u0004 \u0005[לברך]\u0006 \u0003הוא\u0004 ש\u0003לא מברכין, הא אתויי\u0004 \u0005[אבל להביא] —\u0006 \u0003מייתינן\u0004 \u0005[מביאים],\u0006 בניגוד לברייתא הראשונה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 — \u0003בבית האבל\u0004 עצמו אין מביאים בשמים, \u0003הא\u0004 \u0005[כאן]\u0006 — \u0003בבית\u0004 קרוביו \u0003המנחמין\u0004 מביאים בשמים, אבל אין מברכים עליהם.","\u0003אין מוליכין\u0004 את סעודת ההבראה \u0003לבית האבל לא בטבלא\u0004 (שולחן קטן) \u0003ולא באסקוטלא\u0004 (קערה) \u0003ולא בקנון\u0004 (סל שראשו אחד צר) \u0003אלא בסלים. ואין אומרים ברכת אבלים ב\u0004חול ה\u0003מועד, אבל עומדין בשורה\u0004 כשיוצאים האבלים מבית הקברות, \u0003ומנחמין\u0004 אותם, \u0003ופוטרין את הרבים\u0004 שאומרים להם שהם רשאים ללכת לבתיהם לאחר שקיימו מצות תנחומי אבלים.","וכן \u0003אין מניחין את המטה\u0004 של המת \u0003ברחוב\u0004 בחול המועד \u0003שלא להרגיל את ההספד,\u0004 שלא יבואו להספיד ברחוב כפי הנהוג בימות החול. \u0003ולא\u0004 מניחים ברחוב מיטותיהן \u0003של נשים\u0004 מתות \u0003לעולם\u0004 ולא רק בחול המועד, \u0003מפני הכבוד,\u0004 מפני שלפעמים שותת מהן דם ויהא בזיון להן אם ישארו כתמי דם ברחוב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו מוליכין\u0004 את סעודת ההבראה \u0003בבית האבל\u0004 בדרכים שונות, \u0003עשירים\u0004 היו מביאים \u0003בקלתות\u0004 (סלים) \u0003של כסף ושל זהב, ועניים בסלי נצרים של\u0004 ענפי \u0003ערבה קלופה, והיו עניים מתביישים,\u0004 שהכל רואים שעניים הם. \u0003התקינו שיהו הכל מביאין בסלי נצרים של ערבה קלופה, מפני כבודן של עניים.\u0004","כיוצא בו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו משקין בבית האבל\u0004 יין שנותנים לאבל בסעודת הבראה, את ה\u0003עשירים ב\u0004כוסות של \u0003זכוכית לבנה, ו\u0004את ה\u0003עניים ב\u0004כוסות של \u0003זכוכית צבועה, והיו עניים מתביישין,\u0004 שהכל רואים שהם עניים. \u0003התקינו שיהו הכל משקין\u0004 בבית האבל \u0003בזכוכית צבועה, מפני כבודן של עניים.\u0004","ועוד: \u0003בראשונה היו מגלין פני עשירים\u0004 שמתו \u0003ומכסין פני עניים, מפני שהיו מושחרין פניהן מפני\u0004 ה\u0003בצורת, והיו עניים מתביישין\u0004 שהם נקברים בצורה אחרת. \u0003התקינו שיהו מכסין פני הכל, מפני כבודן של עניים.\u0004","ועוד: \u0003בראשונה היו מוציאין\u0004 לקבורה \u0003עשירים בדרגש, ועניים\u0004"],["\u0003בכליכה\u0004 שהיא מיטה המיוחדת למתים ועשויה מוטות שביניהם סירוג, \u0003והיו עניים מתביישין. התקינו שיהו הכל מוציאין בכליכה, מפני כבודן של עניים.\u0004","וכן \u0003בראשונה היו מניחין את המוגמר\u0004 (קטורת) \u0003תחת חולי־מעים מתים\u0004 מפני שהיה ריחם רע, \u0003והיו חולי־מעים חיים מתביישין\u0004 שכך נוהגים בהם במותם, והכל יודעים על כך. \u0003התקינו שיהו מניחין תחת הכל, מפני כבודן של חולי מעים חיים.\u0004","וכן, \u0003בראשונה היו מטבילין את הכלים על גבי\u0004 (משום, בגלל) \u0003נדות מתות,\u0004 נשים שמתו בנדתן היו צריכים לטהר את הכלים שנגעו בהן בחייהן, \u0003והיו נדות חיות מתביישות, התקינו שיהו מטבילין על גבי כל הנשים, מפני כבודן של נדות חיות.\u0004 וכן \u0003בראשונה\u0004 היו \u0003מטבילין\u0004 את הכלים \u0003על גבי\u0004 (משום, בגלל) \u0003זבין מתים\u0004 שמגעם מטמא כלים, \u0003והיו זבין חיים מתביישין\u0004 שכך עושים עליהם במותם, \u0003התקינו שיהו מטבילין על גב הכל, מפני כבודן של זבין חיים.\u0004","ועוד, \u0003בראשונה היתה הוצאת המת קשה לקרוביו יותר ממיתתו\u0004 משום שהיו נוהגים להוציאו בתכריכים יקרים ולא יכלו עניים לשאת בהוצאות, \u0003עד שהיו\u0004 לפעמים \u0003קרוביו מניחין אותו ובורחין. עד שבא רבן גמליאל ונהג קלות ראש בעצמו,\u0004 כלומר, זלזל בכבודו \u0003ויצא\u0004 ציווה להוציא את גופתו \u0003בכלי פשתן, ונהגו העם אחריו לצאת בכלי פשתן. אמר רב פפא: והאידנא נהוג עלמא\u0004 \u0005[ועכשיו\u0006 בזמננו \u0005נוהגים העולם,\u0006 הכל\u0005]\u0006 להוציא את המת \u0003אפילו בצרדא בר זוזא\u0004 \u0005[בבדי קנבוס\u0006 פשוט העולה \u0005זוז\u0006 אחד\u0005]\u0006 ואין מקפידים.","שנינו במשנה ש\u0003אין מניחין\u0004 בחול המועד \u0003את המטה ברחוב. אמר רב פפא: אין מועד\u0004 נחשב \u0003בפני תלמיד חכם\u0004 ולכן מספידים אותו כדרכו אף בחול המועד, \u0003וכל שכן\u0004 ש\u0003חנוכה ופורים\u0004 אינם מעכבים הספדו של חכם.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים כשמספידים אותו \u0003בפניו\u0004 ליד מיטתו, \u0003אבל שלא בפניו — לא.\u0004 ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כך הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב כהנא ספדיה\u0004 \u0005[הספיד]\u0006 את \u0003רב זביד מנהרדעא בפום נהרא\u0004 עירו בחול המועד! \u0003אמר רב פפא: יום שמועה הוה\u0004 \u0005[היה]\u0006 זה, שבו הגיעה השמועה על מותו, \u0003וכבפניו דמי\u0004 \u0005[נחשב].\u0006","ועוד בענייני אבילות, \u0003אמר עולא: הספד\u0004 הוא שאדם מכה \u0003על לב, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"על שדים ספדים\"\u0004 (ישעיהו לב, יב). \u0003טיפוח\u0004 שאמרו הוא כשמכים \u0003ביד\u0004 על יד. \u0003קילוס\u0004 הוא שמכים \u0003ברגל\u0004 על הארץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המקלס\u0004 ומכה ברגלו בארץ לאות אבל — \u0003לא יקלס בסנדל, אלא במנעל, מפני הסכנה.\u0004 מפני שהסנדל עשוי שיקרע ויכול להדקר או להנזק בדרך אחרת.","\u0003אמר ר' יוחנן: אבל, כיון שניענע ראשו\u0004 כמראה שנרגע קצת מצערו \u0003שוב אין מנחמין רשאין לישב אצלו.\u0004 שהוא רומז להם שאינו רוצה בדיבורים נוספים.","\u0003ואמר ר' יוחנן: הכל חייבין לעמוד מפני נשיא, חוץ מאבל וחולה. אמר ר' יוחנן: לכל\u0004 העומדים בפני אדם גדול \u0003אומרים להם \"שבו\",\u0004 ורק אז מותר להם לשבת, \u0003חוץ מאבל וחולה\u0004 שאם עמדו אינם צריכים לקבל רשות לשבת, אלא מותר להם לשבת מרצונם.","\u0003אמר רב יהודה אמר רב: אבל, יום ראשון אסור לאכול לחם משלו.\u0004 ומהיכן אנחנו למדים זאת — \u0003מדאמר ליה רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמר\u0006 לו \u0005הקדוש ברוך הוא]\u0006 \u0003ליחזקאל\u0004 באבלו: \u0003\"ולחם אנשים לא תאכל\"\u0004 (יחזקאל כד, יז), משמע ששאר אבלים אוכלים לחמם של אחרים. ומסופר: \u0003רבה ורב יוסף\u0004 שאירע בהם אבל \u0003מחלפי סעודתייהו להדדי\u0004 \u0005[\u0006היו \u0005מחליפים סעודתם זה לזה].\u0006","\u0003ואמר רב יהודה אמר רב:\u0004 כשיש \u0003מת בעיר — כל בני העיר אסורין בעשיית מלאכה\u0004 עד שיקברוהו.","מסופר: \u0003רב המנונא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום ששמו \u0003דרומתא, שמע קול שיפורא\u0004 \u0005[שופר]\u0006 שמודיע \u0003דשכבא\u0004 \u0005[מת\u0006 בעיר\u0005],\u0006 \u0003חזא הנך אינשי דקא עבדי עבידתא\u0004 \u0005[ראה אי אלה אנשים שעובדים עבודה],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ליהוו הנך אנשי בשמתא\u0004 \u0005[יהיו אנשים אלה בנידוי]!\u0006 וכי \u0003לא שכבא איכא במתא\u0004 \u0005[אין מת בעיר]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003חבורתא איכא במתא\u0004 \u0005[יש חבורות בעיר]\u0006 וכל אחת מהם מתעסקת במתים שלה, ולא בכל המתים כולם ומת זה שידוע לך עליו אינו מחבורתנו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי הכי, שריא לכו\u0004 \u0005[אם כך, מותר לכם]\u0006 הנידוי.","\u0003ואמר רב יהודה אמר רב: כל המתקשה על מתו יותר מדאי\u0004 ואינו רוצה לקבל עליו תנחומים, סופו שגורם לעצמו ש\u0003על מת אחר הוא בוכה.\u0004 ומסופר: \u0003ההיא איתתא דהות בשיבבותיה\u0004 \u0005[אשה אחת שהיתה בשכנותו]\u0006 של \u0003רב הונא, הוו\u0004 \u0005[היו]\u0006 \u0003לה שבעה בני\u0004 \u0005[בנים],\u0006 \u0003מת חד מינייהו\u0004 \u0005[אחד מהם],\u0006 \u0003הוות קא בכיא ביתירתא עליה\u0004 \u0005[היתה בוכה ביותר עליו].\u0006 \u0003שלח לה רב הונא: לא תעבדי הכי\u0004 \u0005[אל תעשי כך]!\u0006 \u0003לא אשגחה ביה\u0004 \u0005[השגיחה בו].\u0006 \u0003שלח לה: אי צייתת\u0004 \u0005[אם תצייתי] —\u0006 \u0003מוטב, ואי\u0004 \u0005[ואם]\u0006 \u0003לא — צבית זוודתא לאידך מית\u0004 \u0005[הכיני תכריכים למת אחר],\u0006 \u0003ומיתו כולהו\u0004 \u0005[ומתו כולם].\u0006 \u0003לסוף\u0004 כשהרבתה לבכות \u0003אמר לה:\u0004 כיון שכך \u0003תימוש זוודתא לנפשיך\u0004 \u0005[הכיני תכריכים לעצמך],\u0006 \u0003ומיתא\u0004 \u0005[ומתה].\u0006","וכך דרשו: \u0003\"אל תבכו למת ואל תנדו לו\"\u0004 (ירמיהו כב, י), ומפרשים כהוראה כללית: \u0003\"אל תבכו למת\" — יותר מדאי, \"ואל תנדו לו\" — יותר מכשיעור. הא כיצד,\u0004 מהו השיעור? \u0003שלשה ימים לבכי, ושבעה להספד, ושלשים ל\u0004איסור \u0003גיהוץ ול\u0004איסור \u0003תספורת. מכאן ואילך — אמר הקדוש ברוך הוא: אי\u0004 \u0005[אין]\u0006 \u0003אתם רחמנים בו יותר ממני\u0004 ואם התורה צוותה רק על אבל זה — די בכך.","בהמשך הפסוק נאמר: \u0003\"בכו בכו להלך\", אמר רב יהודה:\u0004 הכוונה היא \u0003להולך\u0004 מן העולם \u0003בלא בנים,\u0004 שכיון שלא השאיר בנים אחריו האבילות עליו גדולה יותר. וכן מסופר: \u0003ר' יהושע בן לוי לא אזל לבי אבלא\u0004 \u0005[\u0006היה \u0005הולך לבית האבל]\u0006 \u0003אלא למאן דאזיל\u0004 \u0005[למי שהלך,\u0006 מת\u0005]\u0006 \u0003בלא בני\u0004 \u0005[בנים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בכו בכו להלך כי לא ישוב עוד וראה את ארץ מולדתו\"\u0004 (ירמיהו כב, י). ואילו \u0003רב הונא אמר:\u0004 \"הולך\" \u0003זה\u0004 הוא מי \u0003שעבר עבירה ושנה בה\u0004 שהולך וחוטא כל הזמן, והוא לא יגיע לתשובה ומאבד חלקו (\"מולדתו\") לעולם הבא.","ומעירים כי \u0003רב הונא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב הונא: כיון שעבר אדם עבירה ושנה בה — הותרה לו.\u0004 על לשון זו תוהים: \u0003הותרה לו סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! כיצד מותר לו? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן: \u0003נעשית לו כהיתר,\u0004 שלאחר ששנה בה שוב איננו מרגיש את חומרת העבירה שבדבר.","\u0003אמר ר' לוי: אבל, שלשה ימים הראשונים\u0004 אחרי המוות \u0003יראה את עצמו כאילו חרב מונחת לו בין שתי יריכותיו\u0004 שאף הוא עלול ליהרג בה, וצריך לנהוג באימה יתירה. \u0003משלשה עד שבעה כאילו מונחת לו\u0004 החרב \u0003כנגדו בקרן זוית\u0004 ומאיימת עליו, \u0003מכאן ואילך כאילו עוברת כנגדו בשוק\u0004 שאין האיום גדול כל כך.","שנינו במשנה ש\u0003לא מניחים\u0004 מיטה \u0003של נשים לעולם\u0004 ברחוב \u0003מפני הכבוד. אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003לא שנו\u0004"],["כן \u0003אלא\u0004 ב\u0003חיה\u0004 (יולדת), שכיון שמתה מחמת הלידה דמה ממשיך לשתות. \u0003אבל שאר נשים — מניחין\u0004 את מיטתן ברחוב.","\u0003ר' אלעזר אמר: אפילו שאר הנשים\u0004 אין מניחים את מיטתן ברחוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותמת שם מרים ותקבר שם\"\u0004 (במדבר כ, א), ורמז הוא לדבר זה: \u0003סמוך למיתה קבורה,\u0004 שהאשה שמתה ראוי לקרב את הקבורה למקום המיתה.","\u0003ו\u0004על אותו כתוב \u0003אמר ר' אלעזר: אף מרים ב\u0004מיתת \u0003נשיקה\u0004 של ה' \u0003מתה.\u0004 ומהיכן למדים זאת — \u0003אתיא\u0004 \u0005[בא\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המילים \u0003\"שם\" \"שם\" ממשה\u0004 שנאמר בו: \"וימת שם משה עבד ה' בארץ מואב על פי ה' \" (דברים לד, ה). \u0003ומפני מה לא נאמר בה\u0004 במפורש כמו במשה \u0003\"על פי ה' \" — מפני שגנאי הדבר לאומרו\u0004 שמתה אשה בנשיקה של ה', ולכן לא נאמר במפורש.","\u0003אמר ר' אמי: למה נסמכה\u0004 הפרשה העוסקת ב\u0003מיתת מרים לפרשת פרה אדומה — לומר לך: מה פרה אדומה מכפרת, אף מיתתן של צדיקים מכפרת. אמר ר' אלעזר: למה נסמכה מיתת אהרן לבגדי כהונה —\u0004 ללמד: \u0003מה בגדי כהונה מכפרין, אף מיתתן של צדיקים מכפרת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מת\u0004 אדם \u0003פתאום — זו היא מיתה חטופה, חלה יום אחד ומת — זו היא מיתה דחופה. ר' חנניא בן גמליאל אומר: זו היא מיתת מגפה, שנאמר: \"בן אדם הנני לקח ממך את מחמד עיניך במגפה\"\u0004 (יחזקאל כד, טז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בקיומה של נבואה זו \u0003\"ואדבר אל העם בבקר ותמת אשתי בערב\"\u0004 (יחזקאל כד, יח).","חלה \u0003שני ימים ומת — זו היא מיתה דחויה\u0004 (שנדחה, נדחף מחייו והלך לו). חלה \u0003שלשה\u0004 ימים ומת — זוהי מיתת \u0003גערה.\u0004 מת אחר \u0003ארבעה\u0004 ימי מחלה — זוהי מיתת \u0003נזיפה.\u0004 מת אחר \u0003חמישה\u0004 ימים — \u0003זו היא מיתת כל אדם.\u0004","\u0003אמר ר' חנין: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — שנאמר: \u0003\"הן קרבו ימיך למות\"\u0004 (דברים לא, יד), וכך אנחנו דורשים: \u0003\"הן\"\u0004 פירושו \u0003אחד, \"קרבו\"\u0004 הוא לשון רבים — לפחות \u0003תרי\u0004 \u0005[שניים].\u0006 \u0003\"ימיך\"\u0004 גם הוא לשון רבים — שוב \u0003תרי\u0004 \u0005[שניים],\u0006 \u0003הא\u0004 \u0005[הנה]\u0006 \u0003חמשה.\u0004 ומדוע אומרים כי \u0003\"הן\"\u0004 הוא \u0003חד\u0004 \u0005[אחד] —\u0006 \u0003שכן בלשון יוני קורין לאחת \"הן\".\u0004","ועוד מסימני מיתה: \u0003מת\u0004 אדם \u0003ב\u0004גיל \u0003חמשים שנה — זו היא מיתת כרת.\u0004 בן \u0003חמשים ושתים שנה — זו היא מיתתו של שמואל הרמתי.\u0004 מת בן \u0003ששים — זו היא מיתה בידי שמים.\u0004","\u0003אמר מר זוטרא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תבוא בכלח אלי קבר\"\u0004 (איוב ה, כו), \u0003\"בכלח\" בגימטריא שיתין הוו\u0004 \u0005[שישים הם]\u0006 והם רמז שיש בכך עונש משמים.","מת בן \u0003שבעים —\u0004 הרי זו \u0003שיבה.\u0004 מת בן \u0003שמונים —\u0004 הרי זה \u0003גבורות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ימי שנותינו בהם שבעים שנה ואם בגבורת שמונים שנה\"\u0004 (תהלים צ, י). \u0003אמר רבה:\u0004 לא בחמישים בלבד היא מיתת כרת, אלא \u0003מחמשים ועד ששים שנה זו היא מיתת כרת. והאי דלא חשיב להו\u0004 \u0005[ומה שלא מנה אותן]\u0006 את כל השנים הללו כאחת — \u0003משום כבודו של שמואל הרמתי\u0004 שמת בן חמישים ושתים.","מסופר: \u0003רב יוסף כי הוה בר שיתין\u0004 \u0005[כאשר היה,\u0006 נעשה \u0005בן שישים],\u0006 \u0003עבד להו יומא טבא לרבנן\u0004 \u0005[עשה להם יום טוב\u0006 משתה \u0005לחכמים],\u0006 ופירש טעם השמחה, \u0003אמר: נפקי לי\u0004 \u0005[יצאתי]\u0006 \u0003מ\u0004עונש \u0003כרת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: נהי דנפק ליה מר\u0004 \u0005[אם אמנם יצא לו אדוני]\u0006 \u0003מכרת דשני\u0004 \u0005[של שנים],\u0006 \u0003מכרת דיומי\u0004 \u0005[של ימים]\u0006 \u0003מי נפיק מר\u0004 \u0005[האם יצא אדוני]?\u0006 שהרי אמרו שמיתה פתאומית נחשבת כמיתת כרת! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נקוט לך מיהא פלגא בידך\u0004 \u0005[החזק לך על כל פנים חצי בידך]\u0006 שלפחות מאופן אחד של מיתת כרת יצאתי.","מסופר: \u0003רב הונא נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003פתאום, הוו קא דייגי רבנן\u0004 \u0005[היו דואגים החכמים],\u0006 שהרי אמרנו שסימן רע הוא, \u0003תנא להו\u0004 \u0005[שנה להם]\u0006 החכם \u0003זוגא\u0004 שמן המקום \u0003הדייב: לא שנו\u0004 כללים אלה \u0003אלא\u0004 כ\u0003שלא הגיע\u0004 האיש \u0003לגבורות, אבל\u0004 אם \u0003הגיע לגבורות\u0004 ומת פתאום — \u0003זו היא מיתת נשיקה.\u0004","\u0003אמר רבא: חיי, בני ומזוני\u0004 \u0005[\u0006אורך \u0005חיים, בנים ומזונות],\u0006 \u0003לא בזכותא תליא מילתא\u0004 \u0005[בזכות\u0006 האדם \u0005תלוי הדבר],\u0006 \u0003אלא במזלא תליא מילתא\u0004 \u0005[במזל תלוי הדבר].\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רבה ורב חסדא תרוייהו רבנן צדיקי הוו\u0004 \u0005[שניהם חכמים צדיקים היו],\u0006 וסימן לדבר \u0003מר מצלי ואתי מיטרא ומר מצלי ואתי מיטרא\u0004 \u0005[חכם\u0006 זה היה \u0005מתפלל\u0006 בזמן עצירת גשמים \u0005ובא,\u0006 ירד \u0005גשם, וחכם זה\u0006 היה \u0005מתפלל ובא\u0006 ירד \u0005גשם],\u0006 ובכל זאת היו חייהם שונים מאוד,","\u0003רב חסדא חיה תשעין ותרתין שנין\u0004 \u0005[חי תשעים ושתים שנה],\u0006 ואילו \u0003רבה חיה ארבעין\u0004 \u0005[חי ארבעים\u0006 שנה\u0005]\u0006 בלבד, \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב חסדא\u0004 היו \u0003שיתין הלולי\u0004 \u0005[שישים חתונות],\u0006 ואילו \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רבה\u0004 היו \u0003שיתין תיכלי\u0004 \u0005[שישים שכולים,\u0006 אסונות\u0005]\u0006, כלומר בבית רב חסדא היו מאורעות אושר רבים ולהיפך בבית רבה.","\u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב חסדא\u0004 היתה \u0003סמידא לכלבי\u0004 \u0005[\u0006פת \u0005סולת לכלבים]\u0006 \u0003ולא מתבעי\u0004 \u0005[\u0006היתה \u0005מתבקשת],\u0006 שהיה אוכל לרוב, \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רבה נהמא דשערי לאינשי\u0004 \u0005[לחם שעורים לאנשים]\u0006 \u0003ולא משתכח\u0004 \u0005[נמצא].\u0006 מכאן אפשר ללמוד שאורך הימים, בנים, ומזונות אינם תלויים בצידקותו של אדם אלא במזלו.","כיון שהוזכר עושרו של רב חסדא מביאים מה ש\u0003אמר רבא: הני תלת מילי בעאי קמי שמיא\u0004 \u0005[שלושה דברים אלה ביקשתי מלפני השמים],\u0006 \u0003תרתי יהבו\u0004 \u0005[שנים נתנו]\u0006 \u0003לי, חדא\u0004 \u0005[אחד]\u0006 \u0003לא יהבו\u0004 \u0005[נתנו]\u0006 \u0003לי;\u0004 ביקשתי שיתנו לי את \u0003חוכמתיה\u0004 \u0005[חוכמתו]\u0006 של \u0003רב הונא ועותריה\u0004 \u0005[ו\u0006את \u0005עושרו]\u0006 של \u0003רב חסדא, ויהבו\u0004 \u0005[ונתנו]\u0006 \u0003לי.\u0004 ביקשתי שיתנו לי את \u0003ענותנותיה\u0004 \u0005[ענותנותו]\u0006 של \u0003רבה בר רב הונא\u0004 ו\u0003לא יהבו\u0004 \u0005[נתנו]\u0006 \u0003לי.\u0004","ומכאן לסיפורי דברים על מיתת צדיקים. \u0003רב שעורים אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רבא הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רבא, חזייה דהוה קא מנמנם\u0004 \u0005[\u0006ו\u0005ראה אותו שהוא גוסס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאחיו: \u0003לימא ליה מר דלא לצערן\u0004 \u0005[יאמר לו אדוני\u0006 למלאך המוות \u0005שלא יצערני].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שעורים לרבא: \u0003מר לאו שושביניה\u0004 \u0005[\u0006וכי \u0005אדוני לא חבירו]\u0006 של מלאך המוות \u0003הוא?\u0004 שידוע היה שלא היה חושש ממנו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כיון דאימסר מזלא\u0004 \u0005[שנמסר\u0006 ואבד \u0005המזל\u0006 שלי\u0005],\u0006 שנגזר עלי למות, שוב \u0003לא אשגח\u0004 \u0005[משגיח]\u0006 \u0003בי\u0004 מלאך המוות, שאינו שם לב אלי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שעורים לרבא: \u0003ליתחזי\u0004 \u0005[ייראה]\u0006 \u0003לי מר\u0004 \u0005[אדוני]\u0006 בחלום לאחר מיתה. ואכן, \u0003איתחזי ליה\u0004 \u0005[נראה לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שעורים לרבא: \u0003הוה ליה למר צערא\u0004 \u0005[היה לו לאדוני צער]\u0006 במיתה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי ריבדא דכוסילתא\u0004 \u0005[כמו דקירה של הקזת דם].\u0006","כיוצא בזה מסופר: \u0003רבא הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב נחמן, חזייה דקא מנמנם\u0004 \u0005[ראהו שהוא גוסס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבא: \u0003לימא ליה מר דלא לצערן\u0004 \u0005[יאמר לו אדוני\u0006 למלאך המוות \u0005שלא יצערני].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: וכי \u0003מר לאו\u0004 \u0005[אדוני לא]\u0006 \u0003אדם חשוב הוא,\u0004 שמתחשבים בו בשמים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: בעולם עליון \u0003מאן חשיב מאן ספין מאן רקיע\u0004 \u0005[מי חשוב, מי נכבד, מי מתוקן]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב נחמן: \u0003ליתחזי\u0004 \u0005[ייראה]\u0006 \u0003לי מר\u0004 \u0005[אדוני]\u0006 בחלום לאחר מיתה. \u0003איתחזי ליה\u0004 \u0005[נראה לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הוה ליה למר צערא\u0004 \u0005[\u0006וכי \u0005היה לו לאדוני צער\u0006 במיתה\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003כמישחל בניתא מחלבא\u0004 \u0005[כהוצאת שערה מחלב],\u0006 שהיא קלה ביותר, ועם זאת \u0003ואי\u0004 \u0005[ואילו]\u0006 \u0003אמר לי הקדוש ברוך הוא זיל בההוא עלמא כד הוית\u0004 \u0005[לך לאותו עולם,\u0006 עולם הזה, \u0005כמו שהיית] —\u0006 \u0003לא בעינא\u0004 \u0005[\u0006הייתי \u0005רוצה],\u0006 משום \u0003דנפיש ביעתותיה\u0004 \u0005[שמרובה אימתו\u0006 של מלאך המוות\u0005],\u0006 ולא הייתי רוצה לעבור פעם נוספת אימה זו.","ועוד מסופר: \u0003ר' אלעזר הוה קאכיל\u0004 \u0005[היה אוכל]\u0006 \u0003תרומה, איתחזי ליה\u0004 \u0005[נראה לו\u0006 מלאך המוות\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 למלאך המוות: \u0003תרומה קא אכילנא\u0004 \u0005[אני אוכל],\u0006 \u0003ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003קודש איקרי\u0004 \u0005[\u0006היא \u0005נקראת]?\u0006 ואין זה ראוי שאמות כעת ואטמא הקודש. שמע לו מלאך המוות, והניח לו. \u0003חלפא ליה שעתא\u0004 \u0005[עברה לו השעה]\u0006 וחי עוד זמן לאחר מכן.","כיוצא בזה מסופר: \u0003רב ששת איתחזי ליה בשוקא\u0004 \u0005[נראה לו\u0006 מלאך המוות \u0005בשוק],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת למלאך המוות: וכי אמות \u0003בשוקא\u0004 \u0005[בשוק]\u0006 \u0003כבהמה? איתא לגבי ביתא\u0004 \u0005[בוא אל הבית]\u0006 והמיתני שם כדרך בני אדם.","\u0003רב אשי איתחזי ליה בשוקא\u0004 \u0005[נראה לו\u0006 מלאך המוות \u0005בשוק],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי למלאך המוות: \u0003איתרח לי תלתין יומין, ואהדרי לתלמודאי\u0004 \u0005[המתן לי שלושים יום, ואחזור על תלמודי],\u0006 \u0003דאמריתו\u0004 \u0005[שאתם אומרים]\u0006 למעלה: \u0003אשרי מי שבא לכאן\u0004 לעולם הבא \u0003ותלמודו בידו. ביום תלתין\u0004 \u0005[שלושים]\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 מלאך המוות לקחתו. \u0003אמר ליה\u0004 רב אשי למלאך המוות: \u0003מאי כולי האי\u0004 \u0005[מה כל זה],\u0006 מדוע אתה ממהר כל כך, ואינך יכול לדחות את מיתתי? אמר לו: \u0003קא דחקא רגליה\u0004 \u0005[דוחקת\u0006 אותך \u0005רגלו]\u0006 של רב הונא \u0003בר נתן\u0004 שהוא צריך להיות ראש הדור במקומך, \u0003ואין מלכות נוגעת בחבירתה\u0004 ונוטלת ממנה \u0003אפילו כמלא נימא\u0004 (שערה), ולכן אי אפשר להאריך את ימיך.","\u0003רב חסדא, לא הוה יכיל ליה\u0004 \u0005[היה יכול לו\u0006 מלאך המוות\u0005],\u0006 משום ש\u0003לא הוה שתיק פומיה מגירסא\u0004 \u0005[היה פוסק פיו מללמוד],\u0006 \u0003סליק יתיב בארזא\u0004 \u0005[הלך\u0006 מלאך המוות ו\u0005ישב בארז],\u0006 העמוד המרכזי שמחזיק את \u0003דבי\u0004 \u0005[בית]\u0006 \u0003רב. פקע\u0004 ונשבר \u0003ארזא\u0004 \u0005[הארז]\u0006 \u0003ושתק\u0004 רב חסדא, שנבהל רגע מהרעש, \u0003ויכיל ליה\u0004 \u0005[ו\u0006אז \u0005יכול לו].\u0006","\u0003ר' חייא לא הוה\u0004 \u0005[היה]\u0006 מלאך המוות \u0003מצי למיקרבא ליה\u0004 \u0005[יכול להתקרב אליו]\u0006 מפני צידקותו, \u0003יומא חד אידמי ליה כעניא, אתא טריף אבבא\u0004 \u0005[יום אחד נדמה לו\u0006 מלאך המוות \u0005כעני, בא ודפק על הדלת],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפיק\u0004 \u0005[הוצא]\u0006 \u0003לי ריפתא\u0004 \u0005[לחם],\u0006 \u0003אפיקו ליה\u0004 \u0005[הוציאו לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המלאך לרבי חייא: \u0003ולאו קא\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003מרחם מר\u0004 \u0005[אדוני]\u0006 \u0003אעניא\u0004 \u0005[על עני]?\u0006 \u0003אההוא גברא אמאי לא קא מרחם מר\u0004 \u0005[ומדוע אין אדוני מרחם עלי]\u0006 לתת לי את מבוקשי? \u0003גלי ליה\u0004 \u0005[גילה לו]\u0006 מי הוא ומה תפקידו זה \u0003אחוי ליה שוטא דנורא, אמצי ליה נפשיה\u0004 \u0005[הראה לו שוט של אש\u0006 להוכיח שאכן הוא מלאך המוות, ואז \u0005מסר לו את עצמו].\u0006"],["\u0003נשים במועד מענות\u0004 בקול יללה על המת, \u0003אבל לא מטפחות\u0004 בידים משום אבל, \u0003ר' ישמעאל אומר:\u0004 רק \u0003הסמוכות\u0004 ממש \u0003למטה מטפחות.\u0004","\u0003בראשי חדשים, בחנוכה ובפורים\u0004 שאינם ימי חג מן התורה — \u0003מענות ומטפחות, בזה ובזה\u0004 גם במועד וגם בחנוכה ובפורים — \u0003לא מקוננות,\u0004 ולאחר ש\u0003נקבר המת — לא מענות ולא מטפחות.\u0004","ומסבירים: \u0003איזהו עינוי — שכולן עונות כאחת, קינה — שאחת מדברת וכולן עונות אחריה\u0004 בחרוז חוזר, \u0003שנאמר: \"ולמדנה בנתיכם נהי ואשה רעותה קינה\"\u0004 (ירמיהו ט, יט),","וכדי לסיים בדבר טוב, משלימים: \u0003אבל לעתיד לבא הוא אומר \"בלע המות לנצח ומחה ה' אלהים דמעה מעל כל פנים\"\u0004 (ישעיהו כה, ח).","\u0003מאי אמרן\u0004 \u0005[מה אומרות]\u0006 הנשים המענות על המת? \u0003אמר רב:\u0004 אומרות הן \u0003\"ויי לאזלא, ויי לחבילא\"\u0004 \u0005[אוי להולך אוי למשכון],\u0006 שאדם מוסר את נשמתו, שהיא כעין משכון בידו.","\u0003אמר רבא: נשי\u0004 העיר \u0003שכנציב\u0004 שהיו מפורסמות בחכמתן \u0003אמרן הכי\u0004 \u0005[אומרות כך]:\u0006 \u0003\"ויי לאזלא, ויי לחבילא\". ואמר רבא: נשי\u0004 העיר \u0003שכנציב אמרן\u0004 \u0005[אומרות]\u0006 על אדם בזמן זקנותו: \u0003\"גוד גרמא מככא ונמטי מיא לאנטיכי\"\u0004 \u0005[הוצאה העצם מן הלסת וחוזרים המים אל הכלי].\u0006","\u0003ואמר רבא: נשי\u0004 העיר \u0003שכנציב אמרן\u0004 \u0005[אומרות]\u0006 בזמן אבל: \u0003\"עטוף וכסו טורי, דבר רמי ובר רברבי\"\u0004 \u0005[עטפו וכסו הרים\u0006 באבל \u0005שבן רמים ובן גדולים]\u0006 \u0003הוא\u0004 המת. \u0003ואמר רבא: נשי\u0004 העיר \u0003שכנציב אמרן\u0004 \u0005[אומרות]\u0006 \u0003\"שייול אצטלא דמלתא\u0004 \u0005[השאילו בגד מלת\u0006 של תכריכים\u0005]\u0006 \u0003לבר\u0004 \u0005[לבן]\u0006 \u0003חורין, דשלימו זוודיה\"\u0004 \u0005[שנשלמו מזונותיו],\u0006 שבן טובים שירד מנכסיו טוב לו המוות מחייו.","\u0003ואמר רבא: נשי\u0004 העיר \u0003שכנציב אמרן\u0004 \u0005[אומרות]:\u0006 \u0003\"רהיט ונפיל אמעברא ויזופתא יזיף\"\u0004 \u0005[רץ\u0006 אדם \u0005ונופל על המעבורת ו\u0006עדיין \u0005לווה הלוואות].\u0006 \u0003ואמר רבא: נשי\u0004 העיר \u0003שכנציב אמרן\u0004 \u0005[אומרות]:\u0006 \u0003\"אחנא תגרי אזבזגי מיבדקו\"\u0004 \u0005[אחינו התגרים על מקום\u0006 הממכר \u0005נבדקים]\u0006 אם אנשים ישרים הם, ולא בשאר הדברים. \u0003ואמר רבא: נשי\u0004 העיר \u0003שכנציב אמרן\u0004 \u0005[אומרות]:\u0006 \u0003\"מותא כי מותא ומרעין חיבוליא\"\u0004 \u0005[המוות\u0006 הוא \u0005כמו מוות,\u0006 שכל אדם חייב למות, \u0005והיסורים הם כריבית].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003היה ר' מאיר אומר: \"טוב ללכת אל בית אבל\u0004 מלכת אל בית משתה \u0003\"\u0004וגו' \u0003עד \"והחי יתן אל לבו\"\u0004 (קהלת ז, ב), ומה יתן החי אל לבו — \u0003דברים של מיתה,\u0004 והם: \u0003דיספד\u0004 \u0005[\u0006מי \u0005שיספוד]\u0006 \u0003— יספדוניה\u0004 \u0005[יספדו אותו],\u0006 \u0003דיקבר\u0004 \u0005[\u0006מי \u0005שיקבור]\u0006 אחרים — \u0003יקברוניה\u0004 \u0005[יקברו אותו],\u0006 מי ש\u0003יטען,\u0004 כלומר, שיעמיס הרבה דברי הספד על אחרים בלוויה — \u0003יטענוניה\u0004 \u0005[יטענו אותו],\u0006 \u0003דידל\u0004 \u0005[\u0006מי \u0005שירים\u0006 קולו בבכי\u0005]\u0006 \u0003— ידלוניה\u0004 \u0005[ירימו\u0006 אחרים קולם \u0005עליו].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 מי ש\u0003לא ידל\u0004 \u0005[יגביה]\u0006 ולא יגדל את עצמו \u0003ידלוניה\u0004 \u0005[יגביהו אותו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי טוב אמר לך עלה הנה\u0004 מהשפילך לפני נדיב\u0003\"\u0004 (משלי כה, ז).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשמתו בניו של ר' ישמעאל נכנסו ארבעה זקנים לנחמו,\u0004 והם \u0003ר' טרפון ור' יוסי הגלילי ור' אלעזר בן עזריה ור' עקיבא. אמר להם ר' טרפון: דעו שחכם גדול הוא\u0004 ר' ישמעאל \u0003ובקי באגדות, אל יכנס אחד מכם לתוך דברי חבירו,\u0004 אלא כל אחד יאמר דבר לעצמו, וישתדל לאמר דבר חדש. \u0003אמר ר' עקיבא: ואני\u0004 אדבר \u0003אחרון.\u0004","\u0003פתח ר' ישמעאל,\u0004 האבל, \u0003ואמר\u0004 על עצמו: \u0003רבו עונותיו,\u0004 ומשום כך \u0003תכפוהו אבליו,\u0004 ו\u0003הטריח רבותיו פעם ראשונה ושניה\u0004 לנחמו.","כיון שפתח ונתן להם על ידי כך רשות לדבר, \u0003נענה ר' טרפון ואמר:\u0004 כתוב במות בני אהרן \u0003\"ואחיכם כל בית ישראל יבכו את השרפה\"\u0004 (ויקרא י, ו), \u0003והלא דברים קל וחומר: ומה נדב ואביהוא שלא עשו אלא מצוה אחת\u0004 המפורשת בכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקרבו בני אהרן את הדם אליו\"\u0004 (ויקרא ט, ט) והנה \u0003כך\u0004 נאמר עליהם, \u0003בניו של ר' ישמעאל\u0004 שהיו כידוע, מלאים מצוות — \u0003על אחת כמה וכמה.\u0004","\u0003נענה ר' יוסי הגלילי ואמר:\u0004 על אביה בן המלך ירבעם נאמר: \u0003\"וספדו לו כל ישראל וקברו אתו\"\u0004 (מלכים א' יד, יג), \u0003והלא דברים קל וחומר: ומה אביה בן ירבעם שלא עשה אלא דבר אחד טוב, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"יען נמצא בו דבר טוב\"\u0004 (מלכים א' יד, יג), שמשמעו: דבר טוב אחד, \u0003כך\u0004 היה שכרו, \u0003בניו של ר' ישמעאל על אחת כמה וכמה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 אותו \u0003דבר טוב? ר' זירא ור' חיננא בר פפא\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שביטל משמרתו,\u0004 שהושיבו ירבעם אביו בין השומרים שלא להניח אנשים לעלות לרגל לירושלים \u0003ועלה\u0004 בעצמו \u0003לרגל, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שביטל פרדסאות\u0004 (משמרות) \u0003שהושיב ירבעם אביו על הדרכים שלא יעלו ישראל לרגל.\u0004","\u0003נענה ר' אלעזר בן עזריה ואמר:\u0004 נאמר על המלך צדקיהו: \u0003\"בשלום תמות ובמשרפות אבותיך המלכים הראשנים אשר היו לפניך כן ישרפו לך\"\u0004 (ירמיהו לד, ה), \u0003והלא דברים קל וחומר: ומה צדקיהו מלך יהודה שלא עשה אלא מצוה אחת\u0004 שנתפרשה בכתוב, \u0003שהעלה\u0004 את \u0003ירמיה מן הטיט — כך\u0004 נאמר לו, \u0003בניו של ר' ישמעאל על אחת כמה וכמה.\u0004","\u0003נענה ר' עקיבא ואמר,\u0004 נאמר: \u0003\"ביום ההוא יגדל המספד בירושלים כמספד הדדרמון בבקעת מגדון\"\u0004 (זכריה יב, יא), ומעירים, \u0003ואמר רב יוסף: אלמלא תרגומיה דהאי קרא לא הוה ידענא מאי קאמר\u0004 \u0005[אילמלא תרגומו של כתוב זה לא היינו יודעים מה הוא אומר],\u0006 שלא מצינו במקרא מעשה הדדרימון זה, ותרגומו כך הוא:","\u0003בעידנא\u0004 \u0005[בזמן]\u0006 \u0003ההוא יסגי מספדא\u0004 \u0005[ירבה המספד]\u0006 \u0003בירושלים כמספדא\u0004 \u0005[כמספד]\u0006 \u0003אחאב בר עמרי דקטל יתיה\u0004 \u0005[שהרג אותו]\u0006 \u0003הדדרמון בר טברימון, וכמספד\u0004 של \u0003יאשיה בר אמון דקטל יתיה\u0004 \u0005[שהרג אותו]\u0006 \u0003פרעה חגירא\u0004 \u0005[נכה]\u0006 \u0003בבקעת מגידו.\u0004","\u0003והלא דברים קל וחומר: ומה אחאב מלך ישראל שלא עשה אלא דבר אחד טוב, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והמלך היה מעמד במרכבה נכח ארם\"\u0004 (מלכים א' כב, לה), שלא רצה להמלט ולגרום שינוסו ישראל בגללו, \u0003כך\u0004 הספידו אותו, \u0003בניו של ר' ישמעאל על אחת כמה וכמה.\u0004 אגב הזכרת פסוקים אלה דנים בכמה מן הדברים שנזכרו בהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003בצדקיהו \"בשלום תמות\", ו\u0004הרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואת עיני צדקיהו עור\"!\u0004 (ירמיהו לט, ז), \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 מה שאמר לו \"בשלום תמות\", כוונתו \u0003שמת נבוכדנאצר בימיו,\u0004 ולכן מת בשלום שראה במות הרשע.","\u0003ואמר רבא לרבה בר מרי, כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003ביאשיהו: \"ולכן הנני אסיפך על אבתיך ונאספת אל קברתיך בשלום\",\u0004 כאמור (מלכים ב' כב, כ), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וירו הירים למלך יאשיהו\"\u0004 (דברי הימים ב' לה, כג), \u0003ואמר ר' יהודה אמר רב: שעשאוהו\u0004 מרוב חיצים \u0003ככברה\u0004 מלאה נקבים נקבים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר מרי: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 הכוונה \"בשלום\" אצל יאשיהו פירושו — \u0003שלא חרב בית המקדש בימיו\u0004 וכהמשך לפסוק שהובא לפני כן: \"ולא תראינה עיניך בכל הרעה אשר אני מביא על המקום הזה\" (מלכים ב' כב, כ).","\u0003אמר ר' יוחנן: אין מנחמין רשאין לומר דבר\u0004 של תנחומים \u0003עד שיפתח האבל\u0004 וידבר, וראיה לכך \u0003שנאמר: \"\u0004וישבו אתו לארץ שבעת ימים ושבעת לילות ואין דבר אליו דבר כי ראו כי גדל הכאב מאוד. \u0003אחרי כן פתח איוב את פיהו\"\u0004 (איוב ב, יג - ג, א), \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003\"ויען אליפז התימני\"\u0004 (איוב ד, א).","\u0003אמר ר' אבהו: מנין לאבל שמיסב בראש — שנאמר: \"אבחר דרכם ואשב ראש ואשכון כמלך בגדוד כאשר אבלים ינחם\"\u0004 (איוב כט, כה), מכאן שהאבל יושב בראש.","ותוהים: הלא \u0003\"ינחם\" אחריני\u0004 \u0005[ינחם\u0006 את \u0005האחרים]\u0006 \u0003משמע!\u0004 ומכאן יוצא שהמנחם את האבלים הוא היושב בראש! \u0003אמר רב נחמן בר יצחק: \"ינחם\" כתיב\u0004 \u0005[נאמר]\u0006 כלומר, כמו אבל המתנחם.","\u0003מר זוטרא אמר מהכא\u0004 \u0005[מכאן]\u0006 ראיה: \u0003\"וסר מרזח סרוחים\"\u0004 (עמוס ו, ז), ופירושו: \u0003\"מרזח\" —\u0004 מי שהוא מר, ודעתו מטולטלת עליו (זח) באבילות \u0003נעשה שר\u0004 (\"וסר\") \u0003לסרוחים,\u0004 כלומר, לאנשים היושבים לידו נמוך ממנו (\"סרוחים\") לנחמו.","\u0003אמר ר' חמא בר חנינא: מנין לחתן שמיסב בראש — שנאמר: \"כחתן יכהן פאר\"\u0004 (ישעיהו סא, י), \u0003מה כהן\u0004 יושב \u0003בראש — אף חתן\u0004 יושב \u0003בראש.\u0004","ושואלים: \u0003וכהן גופיה\u0004 \u0005[עצמו]\u0006 \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שיושב בראש? ומשיבים: \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 שנאמר בכהן \u0003\"וקדשתו\u0004 כי את לחם אלהיך הוא מקריב\u0003\"\u0004 (ויקרא כא, ח), וכוונתו — ש\u0003לכל דבר שבקדושה\u0004 הוא מקודש מכולם; \u0003לפתוח ראשון\u0004 בקריאה בתורה, \u0003ולברך ראשון\u0004 ברכת המזון, \u0003וליטול מנה יפה\u0004 בסעודה \u0003ראשון.\u0004","ושוב לענין מיתה, \u0003אמר ר' חנינא: קשה יציאת נשמה מן הגוף\u0004"],["\u0003כציפורי בפי הוושט\u0004 \u0005[כמו קשר\u0006 שמוצאים \u0005בפי החבל]\u0006 וקשה להוציא את החבל מהמקום בו הוא קשור, כך גם יציאת הנשמה קשה לגוף. \u0003ר' יוחנן אמר כפטירי\u0004 \u0005[כקשר אוניות]\u0006 שמוציאים בקושי \u0003בפי וושט.\u0004 \u0003ואמר ר' לוי בר חיתא: הנפטר\u0004 (הנפרד) \u0003מן המת, לא יאמר לו \"לך לשלום\" אלא \"לך בשלום\".\u0004 ולהיפך \u0003הנפטר מן החי לא יאמר לו \"לך בשלום\" אלא \"לך לשלום\".\u0004","וראיה לדבר: \u0003הנפטר מן המת לא יאמר לו \"לך לשלום\" אלא \"לך בשלום\", שנאמר: \"ואתה תבוא אל אבתיך בשלום\u0004 תקבר בשיבה טובה\u0003\"\u0004 (בראשית טו, טו). \u0003הנפטר מן החי לא יאמר לו \"לך בשלום\" אלא \"לך לשלום\", שהרי דוד שאמר לאבשלום: \"לך בשלום\"\u0004 (שמואל ב' טו, ט) סופו היה ש\u0003הלך ונתלה,\u0004 ולעומת זה \u0003יתרו שאמר למשה \"לך לשלום\"\u0004 (שמות ד, יח), \u0003הלך והצליח.\u0004 \u0003ואמר ר' לוי: כל היוצא מבית הכנסת לבית המדרש, ומבית המדרש לבית הכנסת —\u0004 שהולך ממצות תפילה למצות לימוד תורה, וממצות לימוד תורה למצות תפילה \u0003זוכה ומקבל פני שכינה, שנאמר: \"ילכו מחיל אל חיל יראה אל אלהים בציון\"\u0004 (תהלים פד, ח).","","","","ועל אותו פסוק \u0003אמר רב חייא בר אשי אמר רב: תלמידי חכמים אין להם מנוחה אפילו לעולם הבא\u0004 שגם שם הם הולכים ומתעלים, \u0003שנאמר: \"ילכו מחיל אל חיל יראה אל אלהים בציון\",\u0004 שגם כאשר הם בעולם הבא, עד אשר תבוא הגאולה באחרית הימים ויראה אלהים בציון, הולכים הם עוד מחיל אל חיל.",""]]};
